#!/bin/sh
# Builds mss32.dll (the Nox Modernized loader, a Miles Sound System proxy) for 32-bit Windows with MinGW-w64.
# loader/mss32_thunks.S, mss32_names.h and mss32.def are generated by tools/gen_mss32.py.
set -e
cd "$(dirname "$0")"
mkdir -p out
i686-w64-mingw32-gcc -std=c11 -O2 -msse2 -mfpmath=sse -Wall -Wextra -Wno-unused-parameter -Wno-cast-function-type -shared \
  -static-libgcc -fno-asynchronous-unwind-tables -Iloader -Igame/ui \
  -o out/mss32-syms.dll loader/*.c loader/mss32_thunks.S game/*/*.c loader/mss32.def -Wl,--enable-stdcall-fixup -ldxguid -lwinmm -lm
i686-w64-mingw32-strip -o out/mss32.dll out/mss32-syms.dll
echo "built out/mss32.dll (symbols: out/mss32-syms.dll)"
